const PREFIX = 'bc-shell-';
const CACHE = SHELL ? PREFIX + SHELL.version : null;
const BASE = new URL('./', self.location).href;
const BASE_PATH = new URL(BASE).pathname;

self.addEventListener('install', (event) => {
  if (!SHELL) return;
  // 新版本装好就接手（和普通网页一样，下次打开即新版）；cache: 'reload' 绕过浏览器 HTTP 缓存，不把旧文件放进新缓存
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // index.html 存在 './' 下：Cloudflare Pages 把 /app/index.html 308 跳到 /app/，跟着跳转拿到的回应带 redirected 标记，
    // 拿它回应页面导航浏览器会报 ERR_FAILED（2026-10-23：第二次打开起整个网站打不开）。直接取 './'，存的时候再去掉跳转标记
    const queue = [...SHELL.files];
    const worker = async () => {
      for (let f; (f = queue.shift()) !== undefined; ) {
        const url = new URL(f === 'index.html' ? './' : f, BASE).href;
        const res = await fetch(new Request(url, { cache: 'reload' }));
        if (!res.ok) throw new Error(`预缓存 ${f} 失败：${res.status}`);
        await cache.put(url, await clean(res));
      }
    };
    await Promise.all(Array.from({ length: 16 }, worker)); // 2000 多个文件，同时取 16 个
    await self.skipWaiting();
  })());
});

// 带 redirected 标记的回应重新包一层（同样的内容、状态、头），可以用来回应页面导航
async function clean(res) {
  if (!res.redirected) return res;
  return new Response(await res.blob(), { status: res.status, statusText: res.statusText, headers: res.headers });
}

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE) await caches.delete(k);
    if (SHELL) await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  if (!SHELL) return;
  const req = event.request;
  if (req.method !== 'GET' || !req.url.startsWith(BASE)) return;
  const rel = new URL(req.url).pathname.slice(BASE_PATH.length);
  // 缺字回退字体（flutter_bootstrap.js 把 fontFallbackBaseUrl 指到这里）：站内不提供、也不去 fonts.gstatic.com，直接 404
  if (rel.startsWith('font-fallback/')) return event.respondWith(new Response('', { status: 404 }));
  if (rel.startsWith('packs/')) return;
  const key = req.mode === 'navigate' && (rel === '' || rel === 'index.html') ? BASE : req;
  event.respondWith((async () => {
    const hit = await caches.match(key, { cacheName: CACHE });
    if (hit) return clean(hit);
    // 外壳里没有的文件（如没内置的章在 assets/ 下的探测）：在线是服务器的 404，断网时也答 404，
    // 让 App 走「没这个文件」的分支，而不是收到网络错误（WebKit 会抛成未捕获的 Load failed）
    return fetch(req).catch(() => (req.mode === 'navigate' ? Response.error() : new Response('', { status: 404 })));
  })());
});
